import{_ as t,o as n,c as o,ak as i}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Chainy learner and session guide","description":"Drafted November 11, 2026 from the lesson-collection game design.\\nThis guide describes planned play; it does not promise these screens or activities exist in a build.\\nCurrent ","frontmatter":{"title":"Chainy learner and session guide","description":"Drafted November 11, 2026 from the lesson-collection game design.\\nThis guide describes planned play; it does not promise these screens or activities exist in a build.\\nCurrent ","source":"docs/user-guide.md","category":"Guides & tooling","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/user-guide.md","filePath":"content/docs/user-guide.md"}'),r={name:"content/docs/user-guide.md"};function s(a,e,l,d,c,h){return n(),o("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-learner-and-session-guide">Chainy learner and session guide<a class="header-anchor" href="#chainy-learner-and-session-guide" aria-label="Link to this section">​</a></h1><p>Drafted November 11, 2026 from the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection game design</a>. This guide describes planned play; it does not promise these screens or activities exist in a build. <strong>Current work is documentation and setup only, with final owner approval required before game development.</strong> Sean owns the authored guide and will reconcile it with the build that is eventually tested.</p><h2 id="start-your-journey">Start your journey<a class="header-anchor" href="#start-your-journey" aria-label="Link to this section">​</a></h2><ol><li>Open the main menu and choose Play.</li><li>Choose an unlocked world; begin with Web3.</li><li>On your first visit, talk to the tutorial guide to learn the island and controls.</li><li>Move with the mobile joystick and use Interact near the current quest&#39;s object, NPC, or facility.</li><li>Follow the Quest log&#39;s lesson order while exploring.</li></ol><p>Web3, Blockchain, and AI each contain thirteen entries. Blockchain opens after Web3 and its required review are complete; AI opens after Blockchain and its required review are complete. You can revisit unlocked worlds.</p><h2 id="use-the-three-main-buttons">Use the three main buttons<a class="header-anchor" href="#use-the-three-main-buttons" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Button</th><th>What it is for</th></tr></thead><tbody><tr><td>Encyclopedia</td><td>Browse collected explanations and examples by Web3, Blockchain, or AI category; each category has thirteen slots</td></tr><tr><td>Quest</td><td>Find your current lesson, next step and landmark hint, earlier completed lessons, and later locked lessons</td></tr><tr><td>Pause</td><td>Stop the activity, review controls, resume, or use the available exit options</td></tr></tbody></table><p>Menus and dialogue prevent accidental movement or world interaction underneath. The collection may display alphabetically while quests follow a teaching order.</p><h2 id="record-a-lesson">Record a lesson<a class="header-anchor" href="#record-a-lesson" aria-label="Link to this section">​</a></h2><p>For an ordinary lesson, find its object, interact, read the meaning and example, then choose Record. Wait for saved confirmation before relying on the new entry or next quest. Later objects do not advance the sequence before their prerequisites are complete. Recorded objects remain useful for review and cannot add the same entry twice.</p><p>Each world has three distinct minigames, making nine across the journey. Your quest may first ask you to collect an item, speak to an NPC, and interact with a facility in that order. The facility opens the lesson&#39;s separate game scene once those requirements are met. Follow its instructions, use its feedback, and retry without losing completed lessons. Retry remains in the minigame; Exit returns to its island without recording that unfinished lesson. Successfully saved completion records the lesson and returns you to its island.</p><h2 id="complete-a-world">Complete a world<a class="header-anchor" href="#complete-a-world" aria-label="Link to this section">​</a></h2><p>Recording all thirteen entries finishes the collection and opens the required review quiz. Complete that review to finish the world and unlock the next one. You may leave or keep exploring before finishing it, but the next world stays locked.</p><p>Answer all 13 questions, one per lesson. Read the explanation and retry each mistake until it is correct. World completion is saved only after all 13 are resolved. Your first-response score remains separate from completing the review after corrections. Leaving an unfinished review starts a new attempt with all 13 questions when you return; already recorded lessons stay saved. Recorded and Complete describe game progress, not proof of mastery.</p><h2 id="saving-and-returning">Saving and returning<a class="header-anchor" href="#saving-and-returning" aria-label="Link to this section">​</a></h2><p>Progress is intended to save locally and work without internet. If saving fails, use Retry Save and wait for confirmation; do not repeatedly collect the object to force progress. Leaving, closing, or changing profiles should resume the last successful checkpoint, not necessarily an exact position or unfinished round. An unfinished minigame restarts its round on re-entry, while completed item and NPC prerequisites remain saved. A local profile does not authenticate identity or recover another phone&#39;s progress.</p><p>All accounts, records, credentials, prices, and messages in lessons are fictional teaching examples. Do not enter real passwords, private keys, recovery phrases, or payment details. AI activities are labeled offline teaching simulations; they do not provide a live chatbot or train a real model from your answers.</p><h2 id="session-preparation-and-evidence">Session preparation and evidence<a class="header-anchor" href="#session-preparation-and-evidence" aria-label="Link to this section">​</a></h2><p>Before using a build with learners, staff must confirm its tested features, limitations, profile setup, and recovery instructions. Collect only permitted evidence and keep participant identities outside repositories and public documents. Community feedback does not automatically establish school-approved pilot evidence or learning improvement. The November 10 session&#39;s actual outcome must come from records; the date alone establishes no completed testing. <strong>Pre-final remains November 21, 2026.</strong></p><p>The older guide&#39;s coin rewards, lantern purchase, and connected-record repair described the superseded economy-led design. Follow the current GDD for lesson collection; consult <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/requirements/product-requirements.html#historical-v2-requirements">historical requirements</a> only when tracing previous work.</p></div>',1)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
